<?php
namespace App\Services\Importaciones;
use App\Models\{Aerodromo,FuenteDato,Importacion};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;
class AnacGeoJsonImporter {
 public function import(string $path):Importacion {
  if(!is_file($path))throw new RuntimeException("No existe el archivo: {$path}");
  $data=json_decode(file_get_contents($path),true,512,JSON_THROW_ON_ERROR);if(($data['type']??null)!=='FeatureCollection')throw new RuntimeException('Se esperaba GeoJSON FeatureCollection.');
  $fuente=FuenteDato::firstOrCreate(['url_referencia'=>config('aeroinfo.sources.dataset.url')],['nombre'=>config('aeroinfo.sources.dataset.name'),'organismo'=>'ANAC / Secretaría de Transporte','tipo_recurso'=>'SHP normalizado a GeoJSON','condiciones_acceso'=>'Dataset público; verificar licencia vigente en la fuente.','frecuencia_actualizacion'=>'Eventual','fecha_ultima_consulta'=>now()->toDateString(),'estado'=>'activa']);
  $run=Importacion::create(['fuente_dato_id'=>$fuente->id,'inicio'=>now(),'resultado'=>'en_proceso']);$stats=['read'=>0,'created'=>0,'updated'=>0,'errors'=>0,'review'=>0];
  DB::beginTransaction();try{foreach($data['features']??[] as $feature){$stats['read']++;try{$p=$feature['properties']??[];$n=trim((string)($p['nombre']??''));if($n===''){throw new RuntimeException('Registro sin nombre normalizado');}$coords=$feature['geometry']['coordinates']??[null,null];$lon=is_numeric($coords[0]??null)?(float)$coords[0]:null;$lat=is_numeric($coords[1]??null)?(float)$coords[1]:null;if($lat!==null&&($lat<-90||$lat>90))throw new RuntimeException('Latitud fuera de rango');if($lon!==null&&($lon<-180||$lon>180))throw new RuntimeException('Longitud fuera de rango');$identity=$p['source_id']??$p['designador_oaci']??$p['designador_local']??sha1($n.'|'.($p['provincia']??'').'|'.$lat.'|'.$lon);$slug=Str::slug(($p['designador_oaci']??$p['designador_local']??$n).'-'.substr(sha1((string)$identity),0,7));$a=Aerodromo::where('source_record_json->source_id',(string)$identity)->first();$values=['slug'=>$slug,'nombre'=>$n,'designador_local'=>$p['designador_local']??null,'designador_oaci'=>$p['designador_oaci']??null,'designador_iata'=>$p['designador_iata']??null,'tipo'=>$p['tipo']??null,'localidad'=>$p['localidad']??null,'provincia'=>$p['provincia']??null,'elevacion_m'=>$p['elevacion_m']??null,'latitud'=>$lat,'longitud'=>$lon,'uso'=>$p['uso']??null,'estado_validacion'=>'pendiente','source_record_json'=>$p];if($a){$safe=array_filter($values,fn($v)=>$v!==null&&$v!=='');$a->fill($safe)->save();$stats['updated']++;}else{$a=Aerodromo::create($values);$stats['created']++;}$a->referencias()->updateOrCreate(['fuente_dato_id'=>$fuente->id,'documento'=>config('aeroinfo.sources.dataset.label')],['url'=>config('aeroinfo.sources.dataset.url'),'fecha_consulta'=>now(),'fecha_importacion'=>now(),'estado_validacion'=>'pendiente','metadatos'=>['source_id'=>$identity]]);if($lat!==null&&$lon!==null)DB::statement('UPDATE aerodromos SET ubicacion=ST_SetSRID(ST_MakePoint(?,?),4326)::geography WHERE id=?',[$lon,$lat,$a->id]);else{$stats['review']++;}}catch(\Throwable $e){$stats['errors']++;}}DB::commit();$run->update(['fin'=>now(),'resultado'=>$stats['errors']?'completado_con_errores':'completado','registros_leidos'=>$stats['read'],'registros_creados'=>$stats['created'],'registros_actualizados'=>$stats['updated'],'errores'=>$stats['errors'],'pendientes_revision'=>$stats['review'],'resumen'=>$stats]);return $run;}catch(\Throwable $e){DB::rollBack();$run->update(['fin'=>now(),'resultado'=>'fallido','errores'=>$stats['errors']+1,'resumen'=>['message'=>$e->getMessage()]]);throw $e;}
 }
}
